  return {
    target,
    // Which way there is worn by the source, as a link wears it (see
    // link_replace.js): `<Button command="--navi-nav-to:/done" replace>`.
    implementation: () =>
      navTo(
        argument,
        linkAsksForReplace(source) ? { replace: true } : undefined,
      ),
  };
