    d.push(`h -${right - tabRight}`); // page bottom ← to tabRight
    d.push(`v ${bottom - junctionY - r}`); // tab right ↓ to (tabRight, bottom-r)
    d.push(arcConvex(r, -r, r)); // tab BR: down→left
