const isTextInputElement = (el) => {
  if (!el) {
    return false;
  }
  if (el.tagName === "TEXTAREA") {
    return true;
  }
  if (el.tagName !== "INPUT") {
    return false;
  }
  const type = el.type || "text";
  return (
    type === "text" ||
    type === "search" ||
    type === "url" ||
    type === "tel" ||
    type === "email" ||
    type === "password" ||
    type === "number"
  );
};

