const SCORE_PHRASE_AT_START = 1;
const SCORE_MULTI_WORD_AT_START = 0.75;
const SCORE_AT_WORD_BOUNDARY = 0.625;
const SCORE_MID_WORD = 0.5;
const SCORE_ACRONYM = 0.4;
const SCORE_BONUS_CASE_EXACT = 0.125;

